	compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
	if compacted == nil {
		compactFailed = true
		continue
	}

	updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
		CheckpointID:      info.CheckpointID,
		SessionID:         content.Metadata.SessionID,
		CompactTranscript: compacted,
	})
	if updateErr != nil {
		logging.Warn(ctx, "failed to backfill compact transcript",
			slog.String("checkpoint_id", string(info.CheckpointID)),
			slog.Int("session_index", sessionIdx),
			slog.String("error", updateErr.Error()),
		)
		compactFailed = true
		continue
	}

	backfilled++
}

if backfilled == 0 && compactFailed {
	fmt.Fprintf(out, "%s skipped (compact transcript backfill failed, see .entire/logs/)\n", prefix)
	return errAlreadyMigrated
}

