backfilled := 0
compactFailed := false

for _, sessionIdx := range needsBackfill {
	content, readErr := v1Store.ReadSessionContent(ctx, info.CheckpointID, sessionIdx)
	if readErr != nil {
		logging.Warn(ctx, "failed to read v1 session for compact backfill",
			slog.String("checkpoint_id", string(info.CheckpointID)),
			slog.Int("session_index", sessionIdx),
			slog.String("error", readErr.Error()),
		)
		compactFailed = true
		continue
	}

	compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
	if compacted == nil {
		// tryCompactTranscript logs specific reasons (no agent, compact error).
		// Log here too for the empty-transcript case.
		if len(content.Transcript) == 0 {
			logging.Warn(ctx, "compact transcript backfill skipped: empty transcript in v1",
				slog.String("checkpoint_id", string(info.CheckpointID)),
				slog.Int("session_index", sessionIdx),
			)
		}
		compactFailed = true
		continue
	}

	updateErr := v2Store.UpdateCommitted(ctx, checkpoint.UpdateCommittedOptions{
		CheckpointID:      info.CheckpointID,
		SessionID:         content.Metadata.SessionID,
		CompactTranscript: compacted,
	})
	if updateErr != nil {
		logging.Warn(ctx, "failed to backfill compact transcript",
			slog.String("checkpoint_id", string(info.CheckpointID)),
			slog.Int("session_index", sessionIdx),
			slog.String("error", updateErr.Error()),
		)
		compactFailed = true
		continue
	}

	backfilled++
}

if backfilled == 0 && compactFailed {
	fmt.Fprintf(out, "%s skipped (compact transcript backfill failed, see .entire/logs/)\n", prefix)
	return errAlreadyMigrated
}

if compactFailed {
	fmt.Fprintf(out, "%s backfilled %d transcript(s) (some failed, see .entire/logs/)\n", prefix, backfilled)
} else {
	fmt.Fprintf(out, "%s backfilled %d transcript(s)\n", prefix, backfilled)
}

