	}

	summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
	if err != nil {
		return fmt.Errorf("failed to read v1 summary: %w", err)
	}
	if summary == nil {
		return fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
	}

